// wantExiftoolTags is the exact selected-tag set runExiftool passes to exiftool
// (output bounding — no makernote megabytes; one-line-extensible). Mirrors the
// refactoring_checklist: assert the arg-slice's tag set without shelling.
var wantExiftoolTags = []string{
	"-ImageWidth", "-ImageHeight", "-FileType",
	"-Make", "-Model", "-DateTimeOriginal",
	"-Orientation", "-GPSLatitude", "-GPSLongitude",
}

// TestExiftoolTags asserts the selected-tag set is the bounded 9-tag list and
// that -j/-n (prepended by runExiftool, not part of the tag list) are absent from
// the tag slice. This is the output-bounding contract (no unbounded dump).
func TestExiftoolTags(t *testing.T) {
	if len(exiftoolTags) != len(wantExiftoolTags) {
		t.Fatalf("exiftoolTags has %d entries, want %d", len(exiftoolTags), len(wantExiftoolTags))
	}
	have := map[string]bool{}
	for _, tg := range exiftoolTags {
		have[tg] = true
	}
	for _, tg := range wantExiftoolTags {
		if !have[tg] {
			t.Errorf("exiftoolTags missing %q", tg)
		}
	}
	for _, tg := range exiftoolTags {
		// -j/-n are JSON/numeric flags prepended in runExiftool, NOT selected tags.
		if tg == "-j" || tg == "-n" {
			t.Errorf("flag %q must not appear in exiftoolTags (prepended by runExiftool)", tg)
		}
	}
}

// TestMapExif is the table test for mapExif (B04, B08, B10): it feeds realistic
// exiftool -j -n JSON objects (decoded the way runExiftool decodes them) and
// asserts the mapped namespace. Covers a full-EXIF JPEG, an EXIF-less PNG (B08 —
// exactly {width,height,format}, non-empty), a Cyrillic Model carried verbatim
// (B10), FileType lowercasing, numeric GPS/orientation, date normalization, and
// absent fields staying absent.
func TestMapExif(t *testing.T) {
	tests := []struct {
		name string
		json string // one exiftool object (the [0] runExiftool returns)
		want map[string]any
	}{
		{
			name: "full_exif_jpeg",
			json: `{"ImageWidth":4000,"ImageHeight":3000,"FileType":"JPEG","Make":"Apple","Model":"iPhone 15","DateTimeOriginal":"2024:07:30 14:21:05","Orientation":6,"GPSLatitude":55.7558,"GPSLongitude":37.6173}`,
			want: map[string]any{
				"width": float64(4000), "height": float64(3000), "format": "jpeg",
				"make": "Apple", "model": "iPhone 15",
				"date_taken":  "2024-07-30T14:21:05Z",
				"orientation": float64(6), "gps_lat": 55.7558, "gps_lon": 37.6173,
			},
		},
		{
			// B08: a valid EXIF-less image still yields {width,height,format} so the
			// namespace is non-empty (clean success, no spurious no_data).
			name: "exifless_png",
			json: `{"ImageWidth":16,"ImageHeight":8,"FileType":"PNG"}`,
			want: map[string]any{"width": float64(16), "height": float64(8), "format": "png"},
		},
		{
			// B09: HEIC FileType lowercases to heic.
			name: "heic_full",
			json: `{"ImageWidth":4032,"ImageHeight":3024,"FileType":"HEIC","Make":"Canon","Model":"EOS R6","DateTimeOriginal":"2023:01:02 03:04:05"}`,
			want: map[string]any{
				"width": float64(4032), "height": float64(3024), "format": "heic",
				"make": "Canon", "model": "EOS R6", "date_taken": "2023-01-02T03:04:05Z",
			},
		},
		{
			// B10: a non-ASCII Model is carried VERBATIM (no re-encoding).
			name: "cyrillic_model_verbatim",
			json: `{"ImageWidth":100,"ImageHeight":100,"FileType":"JPEG","Model":"Фотоаппарат"}`,
			want: map[string]any{
				"width": float64(100), "height": float64(100), "format": "jpeg",
				"model": "Фотоаппарат",
			},
		},
		{
			// An unparseable date is carried verbatim, not dropped or re-encoded.
			name: "unparseable_date_verbatim",
			json: `{"ImageWidth":1,"ImageHeight":1,"FileType":"PNG","DateTimeOriginal":"garbage"}`,
			want: map[string]any{"width": float64(1), "height": float64(1), "format": "png", "date_taken": "garbage"},
		},
	}
	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			tags := decodeExif(t, tc.json)
			got := mapExif(tags)
			if len(got) != len(tc.want) {
				t.Fatalf("mapExif len = %d (%v), want %d (%v) — a dropped or extra field", len(got), got, len(tc.want), tc.want)
			}
			for k, wantV := range tc.want {
				gotV, ok := got[k]
				if !ok {
					t.Errorf("mapExif missing %q (got=%v)", k, got)
					continue
				}
				if gotV != wantV {
					t.Errorf("mapExif[%q] = %v (%T), want %v (%T)", k, gotV, gotV, wantV, wantV)
				}
			}
		})
	}
}

// decodeExif decodes one exiftool JSON object the way runExiftool does (into
// map[string]any, so JSON numbers become float64). Test helper.
func decodeExif(t *testing.T, raw string) map[string]any {
	t.Helper()
	var arr []map[string]any
	if err := json.Unmarshal([]byte("["+raw+"]"), &arr); err != nil || len(arr) != 1 {
		t.Fatalf("decode exif fixture: %v (len=%d)", err, len(arr))
	}
	return arr[0]
}

// TestMapExif_EmptyInput asserts an empty tag map (the soft-fail path: exiftool
// missing/non-zero/non-JSON) maps to an empty namespace (B06).
func TestMapExif_EmptyInput(t *testing.T) {
	if got := mapExif(map[string]any{}); len(got) != 0 {
		t.Fatalf("mapExif({}) = %v, want empty", got)
	}
	if got := mapExif(nil); len(got) != 0 {
		t.Fatalf("mapExif(nil) = %v, want empty", got)
	}
}

// TestRunExiftool_SoftFailMissing is the soft-fail unit test (B06/B07): when
// exiftool is NOT on PATH, runExiftool returns an empty tag map + a non-empty
// warning and never errors. This path is covered REGARDLESS of whether exiftool
// is installed (a missing binary IS the soft-fail trigger).
func TestRunExiftool_SoftFailMissing(t *testing.T) {
	if _, err := exec.LookPath(exiftoolBin); err == nil {
		t.Skip("exiftool is present; the missing-binary soft-fail path is not exercised here")
	}
	tags, warning := runExiftool(context.Background(), "/nonexistent/IMG.jpg")
	if len(tags) != 0 {
		t.Fatalf("tags = %v, want empty when exiftool is missing", tags)
	}
	if warning == "" {
		t.Fatal("warning empty, want a human-readable soft-fail reason")
	}
}

// TestRunExiftool_RealPNG proves the real arg-slice invocation + JSON parse
// (B08): a stdlib-generated PNG yields {ImageWidth,ImageHeight,FileType} tags
// when exiftool is present. Gated on LookPath("exiftool") — skips cleanly when
// exiftool is absent (the soft-fail path is covered by TestRunExiftool_SoftFail).
func TestRunExiftool_RealPNG(t *testing.T) {
	if _, err := exec.LookPath(exiftoolBin); err != nil {
		t.Skip("exiftool not on PATH")
	}
	pngPath := filepath.Join(t.TempDir(), "base.png")
	writePNG(t, pngPath, 12, 7)

	tags, warning := runExiftool(context.Background(), pngPath)
	if warning != "" {
		t.Fatalf("runExiftool warning = %q, want none for a valid PNG", warning)
	}
	if w, ok := numVal(tags, "ImageWidth"); !ok || w != 12 {
		t.Errorf("ImageWidth = %v (ok=%v), want 12", w, ok)
	}
	if h, ok := numVal(tags, "ImageHeight"); !ok || h != 7 {
		t.Errorf("ImageHeight = %v (ok=%v), want 7", h, ok)
	}
	if ft, ok := strVal(tags, "FileType"); !ok || ft != "PNG" {
		t.Errorf("FileType = %q (ok=%v), want PNG", ft, ok)
	}
}

// writePNG generates a tiny valid PNG (w x h) at path via the stdlib encoder, so
// the real-exiftool test has a deterministic, inspectable fixture without a
// committed binary. Dimensions are fixed so assertions are stable.
func writePNG(t *testing.T, path string, w, h int) {
	t.Helper()
	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("create png: %v", err)
	}
	defer f.Close()
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.Set(x, y, color.RGBA{R: uint8(x * 10), G: uint8(y * 10), B: 128, A: 255})
		}
	}
	if err := png.Encode(f, img); err != nil {
		t.Fatalf("encode png: %v", err)
	}
}
